"""Changes the cross section and insulation of a duct route with ModifyMEPRoutingElements.

Creates a temporary duct route, modifies it, reads it back and deletes it. Requires Archicad 28 or later.
"""
import aclib

routeId = aclib.RunTapirCommand ('CreateMEPRoutingElements', {
    'routingElementsData': [{
        'domain': 'Ventilation',
        'nodeCoordinates': [{'x': 0.0, 'y': 0.0, 'z': 2.5}, {'x': 5.0, 'y': 0.0, 'z': 2.5}]
    }]
})['elements'][0]['elementId']

aclib.PrintJson (aclib.RunTapirCommand ('ModifyMEPRoutingElements', {
    'routingElementsData': [{
        'elementId': routeId,
        'crossSectionShape': 'Rectangular',
        'crossSectionWidth': 0.5,
        'crossSectionHeight': 0.25,
        'insulationThickness': 0.05
    }]
}))

aclib.RunTapirCommand ('GetMEPRoutingElements', {'elements': [{'elementId': routeId}]})
aclib.RunTapirCommand ('DeleteElements', {'elements': [{'elementId': routeId}]})

"""Adds a node to a pipe route, then leaves out a node where it goes straight on, with RebuildMEPRoutingElements.

Creates a temporary pipe route, rebuilds it twice, reads it back and deletes it. Requires Archicad 28 or later.

Every segment, node and fitting gets a new guid (see guidMap in the response); labels, dimensions and other
things attached to them are not carried over. Use ModifyMEPRoutingElements nodePositions instead when the node
count stays the same: it keeps every guid. The route keeps its guid when Archicad allows it (else the response
gives the new one), and each new segment keeps the size and settings of the old segment it lies along. Not kept:
the element IDs, classifications, property values and own renovation status of single parts, and the route's
design option; the item's warnings list anything else not carried over. A route that ends at a tee or has a
take-off is refused, since Archicad deletes those with the route.
"""
import aclib

routeId = aclib.RunTapirCommand ('CreateMEPRoutingElements', {
    'routingElementsData': [{
        'domain': 'Piping',
        'nodeCoordinates': [{'x': 0.0, 'y': 0.0, 'z': 2.5}, {'x': 4.0, 'y': 0.0, 'z': 2.5}]
    }]
})['elements'][0]['elementId']

# Adds a bend point at the end: the route goes on 3 m to the north.
routeId = aclib.RunTapirCommand ('RebuildMEPRoutingElements', {
    'routingElements': [{
        'routingElementId': routeId,
        'nodeCoordinates': [{'x': 0.0, 'y': 0.0, 'z': 2.5}, {'x': 4.0, 'y': 0.0, 'z': 2.5}, {'x': 4.0, 'y': 3.0, 'z': 2.5}]
    }]
})['elements'][0]['elementId']

# The node at x 2 lies on the straight line from x 0 to x 4, so it is left out.
response = aclib.RunTapirCommand ('RebuildMEPRoutingElements', {
    'routingElements': [{
        'routingElementId': routeId,
        'nodeCoordinates': [{'x': 0.0, 'y': 0.0, 'z': 2.5}, {'x': 2.0, 'y': 0.0, 'z': 2.5}, {'x': 4.0, 'y': 0.0, 'z': 2.5}, {'x': 4.0, 'y': 3.0, 'z': 2.5}],
        'removeCollinearNodes': True
    }]
})
aclib.PrintJson (response)
routeId = response['elements'][0]['elementId']

aclib.RunTapirCommand ('GetMEPRoutingElements', {'elements': [{'elementId': routeId}]})
aclib.RunTapirCommand ('DeleteElements', {'elements': [{'elementId': routeId}]})

"""Changes MEP ports with ModifyMEPPorts: the flow direction and outer diameter of a piping terminal's port, and
the connection size (width and height) of an air terminal.

Creates a temporary piping terminal and a ventilation terminal, modifies their ports, reads them back and
deletes them. GetMEPPorts reads the ports of MEP elements such as terminals, not of routes. Requires Archicad 28
or later.
"""
import aclib

pipeTerminalId, airTerminalId = [element['elementId'] for element in aclib.RunTapirCommand ('CreateMEPElements', {
    'elementsData': [
        {'type': 'Terminal', 'domain': 'Piping', 'position': {'x': 0.0, 'y': 0.0, 'z': 1.0}},
        {'type': 'Terminal', 'domain': 'Ventilation', 'position': {'x': 0.0, 'y': 2.0, 'z': 2.5}}
    ]
})['elements']]

ports = aclib.RunTapirCommand ('GetMEPPorts', {'elements': [{'elementId': pipeTerminalId}, {'elementId': airTerminalId}]})['elementPorts']
pipePort = ports[0]['ports'][0]
airPort = ports[1]['ports'][0]

aclib.PrintJson (aclib.RunTapirCommand ('ModifyMEPPorts', {
    'portsData': [
        {
            'portId': pipePort['portId'],
            'flowDirection': 'FlowIn',
            'outerDiameter': 0.05
        },
        {
            'portId': airPort['portId'],
            'shape': 'Rectangular',
            'width': 0.4,
            'height': 0.25
        }
    ]
}))

aclib.RunTapirCommand ('GetMEPPorts', {'elements': [{'elementId': pipeTerminalId}, {'elementId': airTerminalId}]})
aclib.RunTapirCommand ('DeleteElements', {'elements': [{'elementId': pipeTerminalId}, {'elementId': airTerminalId}]})

"""Connects a branch duct to the middle of a main duct with ConnectMEPElements, which creates a branch element.

Creates the two duct routes; the branch starts on the main route, as the command needs. Requires Archicad 28 or later.
"""
import aclib

mainId, branchId = [element['elementId'] for element in aclib.RunTapirCommand ('CreateMEPRoutingElements', {
    'routingElementsData': [
        {
            'domain': 'Ventilation',
            'nodeCoordinates': [{'x': 0.0, 'y': 0.0, 'z': 2.5}, {'x': 8.0, 'y': 0.0, 'z': 2.5}]
        },
        {
            'domain': 'Ventilation',
            'nodeCoordinates': [{'x': 4.0, 'y': 0.0, 'z': 2.5}, {'x': 4.0, 'y': 3.0, 'z': 2.5}]
        }
    ]
})['elements']]

aclib.PrintJson (aclib.RunTapirCommand ('ConnectMEPElements', {
    'connectionsData': [{
        'routingElementId': mainId,
        'connectToId': branchId
    }]
}))

"""Checks with CheckMEPPortConnectability whether the end port of one duct can be connected to the ports of another.

Creates two temporary duct routes that meet at one point and deletes them at the end.
The command itself works from Archicad 27; creating the routes requires Archicad 28 or later.
"""
import aclib

routeIds = [element['elementId'] for element in aclib.RunTapirCommand ('CreateMEPRoutingElements', {
    'routingElementsData': [
        {
            'domain': 'Ventilation',
            'nodeCoordinates': [{'x': 0.0, 'y': 0.0, 'z': 2.5}, {'x': 5.0, 'y': 0.0, 'z': 2.5}]
        },
        {
            'domain': 'Ventilation',
            'nodeCoordinates': [{'x': 5.0, 'y': 0.0, 'z': 2.5}, {'x': 5.0, 'y': 5.0, 'z': 2.5}]
        }
    ]
})['elements']]
firstPorts, secondPorts = [item['ports'] for item in aclib.RunTapirCommand ('GetMEPPorts', {
    'elements': [{'elementId': routeId} for routeId in routeIds]
})['elementPorts']]

aclib.PrintJson (aclib.RunTapirCommand ('CheckMEPPortConnectability', {
    'portPairs': [{'portId': firstPorts[-1]['portId'], 'otherPortId': port['portId']} for port in secondPorts]
}))

aclib.RunTapirCommand ('DeleteElements', {'elements': [{'elementId': routeId} for routeId in routeIds]})

"""Adds a cable carrier segment table, renames it and fills it with rows using ModifyMEPPreferenceTables, then deletes it.

Requires Archicad 28 or later.
"""
import aclib

tableGuid = aclib.RunTapirCommand ('ModifyMEPPreferenceTables', {
    'domain': 'CableCarrier',
    'tablesToAdd': [{'type': 'Segment', 'name': 'Tapir example'}]
})['addedTables'][0]['guid']

aclib.PrintJson (aclib.RunTapirCommand ('ModifyMEPPreferenceTables', {
    'domain': 'CableCarrier',
    'tables': [{
        'guid': tableGuid,
        'name': 'Tapir example (renamed)',
        'newRows': [
            {'value': 0.1, 'description': '100'},
            {'value': 0.2, 'description': '200'}
        ]
    }]
}))

tables = aclib.RunTapirCommand ('GetMEPPreferenceTables', {'domain': 'CableCarrier'})['cableCarrierTables']
print (next (table for table in tables if table['guid'] == tableGuid))

aclib.PrintJson (aclib.RunTapirCommand ('ModifyMEPPreferenceTables', {
    'domain': 'CableCarrier',
    'tablesToDelete': [tableGuid]
}))

