aclib.RunTapirCommand ('GetMEPSystemGroups', {})

aclib.PrintJson (aclib.RunTapirCommand ('ModifyMEPPhysicalSystems', {
    'physicalSystemsData': [{'physicalSystemId': physicalSystem['physicalSystemId'], 'name': physicalSystem['name']}]
}))

